const ACTIVE_TASK_IDS = [1, 2, 4, 5, 6, 7, 8, 9] as const;
const TASK_TOTAL = ACTIVE_TASK_IDS.length;
const taskDisplayNumbers: Record<number, number> = { 1: 1, 2: 2, 4: 3, 5: 4, 6: 5, 7: 6, 8: 7, 9: 8 };
const taskDurations: Record<number, number> = { 1: 7, 2: 2, 4: 10, 5: 4, 6: 5, 7: 8, 8: 7, 9: 4 };

function taskDisplayNumber(task: number) {
  return taskDisplayNumbers[task] ?? task;
}

function nextActiveTask(task: number) {
  const index = ACTIVE_TASK_IDS.indexOf(task as (typeof ACTIVE_TASK_IDS)[number]);
  return index >= 0 ? ACTIVE_TASK_IDS[index + 1] : undefined;
}

