const mailItems: Array<Omit<MailRecord, 'read' | 'flagged' | 'folder'>> = [
  { id: 'mail-13', sender: 'Тарик Елена, проектный офис', email: 'elena.tarik@changellenge.ru', subject: 'Полезные идеи по созданию ИИ-помощников', preview: 'При проектировании ИИ-помощника важно начинать с потребностей пользователей.', body: 'Коллеги, привет!\n\nПродолжаем серию рассылок «Наши инсайты». Сегодня собрали полезные идеи по созданию ИИ-помощников.\n\nПри проектировании ИИ-помощника важно начинать не с технологий, а с потребностей пользователей. Не стоит ограничиваться формулировками «нужна база знаний» или «нужен чат-бот». Лучше определить, что пользователь хочет изменить в своей работе: например, «хочу быстро найти нужную информацию и быть уверен, что использую актуальные правила» или «хочу тратить время на решение рабочих задач, а не на поиск доступов и ответственных».\n\nФункционал помощника должен напрямую отвечать на эти потребности. Помимо стандартного поиска и ответов, полезно показывать, насколько надёжен ответ, предупреждать, если информации недостаточно или документы противоречат друг другу, а также определять момент, когда вопрос лучше передать специалисту, и готовить для него краткое описание ситуации.\n\nВ первую версию стоит включать не все интересные функции, а только те, которые решают наиболее частые и значимые проблемы пользователей, используют доступные данные и дают понятный эффект.', date: '09:11', unread: true, icon: 'ЕТ' },
  { id: 'mail-12', sender: 'Тарик Елена, проектный офис', email: 'elena.tarik@changellenge.ru', subject: 'Внешние ориентиры по адаптации сотрудников', preview: 'Ориентиры по срокам адаптации и формулы бизнес-эффекта.', body: 'Коллеги, привет!\n\nСобрали ориентиры по ключевым показателям адаптации для разных типов ролей. Значения являются ориентирами для сравнения, поскольку фактический срок выхода на продуктивность сильно зависит от сложности работы, систем и требований к роли.\n\nОриентиры по сроку выхода на 100% производительности: технический блок — 60–90 дней, ИТ-блок — 60–90 дней, розничный блок — 30–45 дней, контактный центр — 45–60 дней. Время до самостоятельной работы: 45–60, 30–45, 14–30 и 21–35 дней соответственно.\n\nТакже делимся практиками по расчёту бизнес-эффекта:\n• сокращение времени выхода на 100% эффективность = количество новичков × количество сокращённых дней × стоимость рабочего дня × недополученная производительность;\n• сокращение текучести = количество предотвращённых уходов × стоимость замены сотрудника;\n• высвобождение времени наставников = количество наставников × количество сэкономленных часов × стоимость часа;\n• сокращение времени поиска информации новичками.', date: '09:10', unread: true, icon: 'ЕТ' },
  { id: 'mail-11', sender: 'Круглова Влада', email: 'vlada.kruglova@changellenge.ru', subject: 'Адаптация в техническом блоке', preview: 'Новичкам сложно разобраться в инфраструктуре и расставить приоритеты.', body: 'Привет!\n\nПо наблюдениям руководителей, новичкам сложно быстро разобраться, как устроена инфраструктура и связаны разные участки работы. Также в первые недели им трудно самостоятельно расставлять приоритеты при большом количестве параллельных задач. Не всегда понятно, к кому обращаться, если задача выходит за рамки их участка, а некоторым сотрудникам не хватает уверенности при работе с новым оборудованием и инструментами.\n\nПо нашему опыту около 60% сотрудников готовы активно использовать новые цифровые инструменты.\n\nВ ИИ-помощнике я бы рассмотрел поиск по технической документации, автоматическое планирование работ, подсказки по диагностике оборудования, напоминания о проверках и подготовку отчётов.\n\nПри этом опасаюсь, что ошибка ИИ может привести к неправильным действиям с оборудованием. Важно контролировать актуальность источников и не допустить, чтобы сотрудники доверяли ИИ больше, чем действующим регламентам.', date: '09:09', unread: true, icon: 'ВК' },
  { id: 'task', sender: 'Марина Орлова', email: 'marina.orlova@changellenge.ru', subject: 'Разработка ИИ-помощника', preview: 'Подготовьте концепцию ИИ-помощника для новых сотрудников.', date: '09:08', unread: true, icon: 'МО' },
  { id: 'mail-9', sender: 'Екатерина Смирнова, HR бизнес-партнёр', email: 'ekaterina.smirnova@changellenge.ru', subject: 'Аналитика по адаптации сотрудников', preview: 'Данные по техническому, ИТ- и розничному блокам.', body: 'Привет, коллеги!\n\nУ нас в компании есть три самых крупных подразделения:\n• технический блок отвечает за развитие и эксплуатацию телекоммуникационной инфраструктуры;\n• ИТ-блок разрабатывает и поддерживает внутренние и клиентские ИТ-системы;\n• розничный блок работает с клиентами в офисах продаж, консультирует по продуктам и услугам, оформляет подключения и продаёт оборудование.\n\nНаправляю аналитику по адаптации в этих блоках.\n\nТехнический блок: 650 новичков в год, 90 дней до 100% производительности, 10% не проходят испытательный срок, 42 дня до самостоятельной работы.\nИТ-блок: 420 новичков в год, 80 дней до 100% производительности, 12% не проходят испытательный срок, 30 дней до самостоятельной работы.\nРозничный блок: 630 новичков в год, 60 дней до 100% производительности, 12% не проходят испытательный срок, 14 дней до самостоятельной работы.\n\nКатегория информации К2 — коммерческая тайна.', date: '09:07', unread: true, icon: 'ЕС' },
  { id: 'mail-8', sender: 'Ольга Петрова, руководитель клиентской поддержки', email: 'olga.petrova@changellenge.ru', subject: 'Что мешает быстрой адаптации', preview: 'Обратная связь руководителей офисов продаж.', body: 'Привет!\n\nПо обратной связи от руководителей офисов, новичкам сложно запомнить большое количество продуктов и условий. В первые недели им также трудно сохранять спокойствие в конфликтных ситуациях с клиентами и подобрать нужные слова для ответа. Ещё одна проблема — необходимость быстро переключаться между консультациями, оформлением операций, документами и внутренними системами. Кроме того, сотрудники не всегда понимают, какие действия помогут им выполнить план продаж.\n\nБольшинство сотрудников готовы попробовать новые цифровые инструменты.\n\nВ ИИ-помощнике я бы рассмотрела персональные рекомендации по продуктам, подсказки по продажам, тренажёр диалогов, автоматические итоги рабочего дня и рекомендации по обучению.\n\nЯ бы осторожно относилась к пилоту: ошибка в рекомендации может повлиять на клиента. Кроме того, важно убедиться, что он действительно экономит время, а не создаёт дополнительные переключения.', date: '09:06', unread: true, icon: 'ОП' },
  { id: 'mail-7', sender: 'Марина Орлова', email: 'marina.orlova@changellenge.ru', subject: 'Корпоративный забег', preview: 'В эту субботу пройдёт корпоративный забег.', body: 'Привет!\n\nВ эту субботу пройдёт наш корпоративный забег. Встречаемся в городском парке у центрального входа в 10:00. Забег организуем для сотрудников, чтобы вместе провести время вне работы, поддержать командный дух и немного размяться.\n\nОсновная дистанция — 5 км. Можно пробежать её в своём темпе или прийти поддержать коллег в качестве болельщика.\n\nПодскажите, пожалуйста, планируете присоединиться? Если да, будете участвовать в забеге или болеть за команду? Жду ваших ответов до конца рабочего дня.', date: '09:05', unread: true, icon: 'МО' },
  { id: 'mail-6', sender: 'Олег Сафронов', email: 'oleg.safronov@changellenge.ru', subject: 'Результаты аудита регламентов и процессов', preview: 'Сводка по объёму, актуальности и структуре документов.', body: 'Привет!\n\nМы с коллегами провели большую работу по аудиту процессов и документации по подразделениям. Мне кажется, эта информация может быть тебе полезна в рамках проекта.\n\nТехнический блок: 8 400 документов, актуальны 67%, понятная структура у 61%, ответственный указан у 43%.\nИТ-блок: 6 200 документов, актуальны 89%, понятная структура у 82%, ответственный указан у 67%.\nРозничный блок: 3 100 документов, актуальны 84%, понятная структура у 76%, ответственный указан у 71%.', date: '09:04', unread: true, icon: 'ОС' },
  { id: 'mail-5', sender: 'Семенова Анна, аналитик', email: 'anna.semenova@changellenge.ru', subject: 'ТОП обращений новичков в Service Desk', preview: 'Популярные и повторяющиеся обращения новичков.', body: 'Коллеги, привет!\n\nОтправляю отчёт по четырём наиболее популярным обращениям и отдельно информацию по частоте повторяющихся обращений от одного сотрудника.\n\nГде найти информацию: технический блок 19%, ИТ-блок 16%, розничный блок 27%.\nКак выполнить типовую операцию: 24%, 20%, 31%.\nК кому обратиться: 11%, 9%, 14%.\nКак оформить доступ: 6%, 12%, 5%.\nПовторяющиеся обращения: 51%, 43%, 68%.', date: '09:03', unread: true, icon: 'АС' },
  { id: 'mail-4', sender: 'Екатерина Смирнова, HR бизнес-партнёр', email: 'ekaterina.smirnova@changellenge.ru', subject: 'Причины увольнения на испытательном сроке', preview: 'Результаты опроса о причинах увольнений.', body: 'Дорогие коллеги!\n\nОтправляю данные опроса о причинах увольнений на испытательном сроке. Сотрудник мог выбрать несколько причин, поэтому сумма процентов не равна 100%.\n\nНе справился с обязанностями: технический блок 34%, ИТ-блок 27%, розничный блок 38%.\nРабота оказалась не такой, как ожидал: 25%, 46%, 26%.\nНе хватало обучения и поддержки: 45%, 21%, 33%.\nСложно разобраться в процессах и системах: 52%, 29%, 40%.\nНе хватало оборудования, доступов или ПО: 35%, 43%, 28%.\nСложности в коммуникации: 23%, 19%, 28%.', date: '09:02', unread: true, icon: 'ЕС' },
  { id: 'mail-3', sender: 'Информационная безопасность', email: 'security@changellenge.ru', subject: 'Правила работы с корпоративным ИИ', preview: 'Простые правила безопасной работы с ИИ.', body: 'Познакомьтесь с простыми правилами работы с ИИ.\n\nИспользуйте только корпоративный ИИ для анализа рабочей информации. Не передавайте внутренние данные в публичные ИИ-сервисы.\n\nНе загружайте даже в корпоративный ИИ конфиденциальную информацию, включая персональные данные сотрудников и клиентов, финансовую информацию, коммерческую тайну, пароли, доступы и другую защищённую информацию.\n\nПроверяйте результаты работы ИИ перед использованием. ИИ может допускать ошибки, поэтому итоговое решение всегда принимает сотрудник. Ответственность за итоговый результат остаётся у сотрудника: использование ИИ помогает ускорить работу, но не заменяет профессиональную оценку.', date: '09:01', unread: true, icon: 'ИБ' },
  { id: 'mail-2', sender: 'Светлана Трушкина', email: 'svetlana.trushkina@changellenge.ru', subject: 'Обновление шаблонов презентаций', preview: 'Новый шаблон корпоративной презентации.', body: 'Привет! Отправляю новый шаблон корпоративной презентации, пожалуйста, используйте его для оформления внутренних проектов.', date: '09:00', unread: true, icon: 'СТ' },
  { id: 'mail-1', sender: 'Алексей Воронцов, руководитель разработки', email: 'alexey.vorontsov@changellenge.ru', subject: 'Обратная связь от новичков в ИТ-блоке', preview: 'Новичкам трудно погрузиться в контекст команды.', body: 'Привет!\n\nГлавная сложность для новичков — быстро погрузиться в контекст команды и понять особенности работы над продуктом. Также им бывает трудно разобраться во внутренних сокращениях и терминах, а большое количество встреч в первые недели мешает сосредоточиться на рабочих задачах. Некоторые сотрудники долго не понимают границы своей ответственности и когда решение нужно принимать самостоятельно.\n\nНаши сотрудники регулярно применяют ИИ в личных, учебных и рабочих целях.\n\nИз функций помощника я бы рассмотрел подготовку к встречам, резюме переписки, подбор обучающих материалов, рекомендации по развитию навыков и вопросы о структуре команды.\n\nОсновной риск — безопасность: нужно чётко определить, какую информацию можно передавать ИИ. Также важно не допустить, чтобы помощник заменил общение с коллегами или выдавал слишком общие рекомендации.', date: '08:59', unread: true, icon: 'АВ' },
];

