function buildContextualMailResponse(mail: MailRecord, optionIndex: number): MailRecord | null {
  const option = contextualMailReplyOptions[mail.id]?.[optionIndex];
  const body = contextualMailAutoResponses[mail.id]?.[optionIndex];
  if (!option || !body) return null;
  const isForward = option.action === 'forward';
  return {
    id: `auto-reply-${mail.id}`,
    sender: isForward ? 'Проектная команда' : mail.sender,
    email: isForward ? 'project-team@changellenge.ru' : mail.email,
    subject: `Re: ${isForward ? 'Fwd: ' : ''}${mail.subject}`,
    preview: body,
    body,
    date: 'сейчас',
    unread: true,
    read: false,
    flagged: false,
    folder: 'inbox',
    icon: isForward ? 'ПК' : mail.icon,
  };
}

