const mail17: MailRecord = {
  id: 'mail-17', sender: 'Марина Орлова', recipient: 'Проектная команда', email: 'marina.orlova@changellenge.ru', subject: 'Разработка ИИ-помощника для контактного центра',
  preview: 'Оцените предложение и предложите критерии и план пилота.',
  body: 'Коллеги, спасибо большое за участие в совещании. Мы приняли нестандартное решение провести пилот на целевой аудитории, которую изначально не рассматривали, — новичках контактного центра. Благодаря тому, что они работают всего на трёх площадках в России, нам будет легче организовать информирование и собрать обратную связь, чтобы понять эффект проекта.\n\nВ контактном центре ежегодно начинает работу около 1 800 новых сотрудников. Средний срок выхода на 100% производительности — 50 дней, 11% новичков не проходят испытательный срок, до начала самостоятельной работы сотруднику в среднем требуется 35 дней.\n\nНовичкам сложно быстро ориентироваться в большом количестве информации и применять её непосредственно во время разговора с клиентом. Особенно сложно уверенно общаться с клиентами, сохранять спокойствие в конфликтных ситуациях и быстро переключаться между клиентом, документами и внутренними системами.\n\nПо данным Service Desk, 34% обращений связаны с поиском информации, 38% — с выполнением типовой операции, 18% — с поиском ответственного. Доля повторяющихся обращений составляет 76%. Среди причин увольнения на испытательном сроке: 41% сотрудников не справились с обязанностями, 44% отметили недостаток обучения и поддержки, 35% — сложности с внутренними процессами и системами, 34% — сложности в коммуникации с коллегами или руководителем, 53% — высокую нагрузку и стресс.\n\nВ качестве функций ИИ-помощника можно рассмотреть поиск по внутренним инструкциям, подсказки по типовым операциям, рекомендации по продуктам, определение следующего шага и передачу сложного вопроса специалисту. Также могут быть полезны тренажёр сложных диалогов и подсказки по формулировке ответа клиенту.\n\nКлючевые потребности новичков: быстро находить нужную информацию и понимать, какую инструкцию применять; получать помощь с типовыми операциями; понимать, к кому обратиться со сложным вопросом; увереннее общаться с клиентами; снижать стресс; быстро переключаться между системами; понимать, правильно ли сотрудник отвечает клиенту.\n\nВ пилотную версию предложено включить поиск по всем доступным корпоративным документам, подсказки по типовым операциям и необходимым проверкам, рекомендации по следующему шагу и ответственному, автоматическую проверку каждого ответа клиенту, тренажёр сложных диалогов, подсказки в конфликтных ситуациях и персональные рекомендации по снижению стресса на основе рабочих диалогов.\n\nВнимательно оцените предложение, дайте обратную связь и предложите показатели, по которым можно оценить эффективность пилота.',
  date: 'сейчас', unread: true, read: false, flagged: true, folder: 'inbox', icon: 'МО',
};

