function TaskBrief({ task }: { task: number }) {
  const brief = taskBriefs[task];
  if (!brief) return null;
  return <div className="task-brief"><p>{brief.intro}</p><strong>Для этого:</strong><ul>{brief.actions.map((action) => <li key={action}>{action}</li>)}</ul><p className="task-brief-time">На выполнение задания у вас {brief.minutes} {brief.minutes === 2 || brief.minutes === 4 ? 'минуты' : 'минут'}</p></div>;
}

function AutosizeTextarea(props: TextareaHTMLAttributes<HTMLTextAreaElement>) {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resize = () => {
    const textarea = textareaRef.current;
    if (!textarea) return;
    textarea.style.height = '0px';
    textarea.style.height = `${Math.min(textarea.scrollHeight, 180)}px`;
  };
  useEffect(resize, [props.value]);
  return <textarea {...props} ref={textareaRef} rows={1} onInput={(event) => { resize(); props.onInput?.(event); }} />;
}

